  try {
    const res = await fetch(`/api/bookings/${bookingId}/cancel`, { method: 'POST' });
    const data = await res.json();

    if (!res.ok) {
      showToast(data.error || 'Erro ao cancelar reserva.', 'error');
      return;
    }

    showToast('Reserva cancelada com sucesso.', 'success');
    loadMyBookings();
